declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    select outbox.notification_id
    from public.v1_notification_push_outbox outbox
    where (
      outbox.status in ('pending', 'failed')
      and outbox.next_attempt_at <= clock_timestamp()
    ) or (
      outbox.status = 'sending'
      and outbox.lease_until < clock_timestamp()
    )
    order by outbox.created_at
    limit 25
  loop
    if public.v1_dispatch_push_notification(v_row.notification_id) then
      v_count := v_count + 1;
    end if;
  end loop;
  return v_count;
end;

declare
  v_url text;
  v_secret text;
begin
  if to_regclass('vault.decrypted_secrets') is null then
    return false;
  end if;
  execute
    'select decrypted_secret from vault.decrypted_secrets where name = $1 limit 1'
    into v_url using 'yorks_push_edge_url';
  execute
    'select decrypted_secret from vault.decrypted_secrets where name = $1 limit 1'
    into v_secret using 'yorks_push_webhook_secret';
  if nullif(v_url, '') is null or nullif(v_secret, '') is null then
    return false;
  end if;
  perform net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-yorks-push-secret', v_secret
    ),
    body := jsonb_build_object('notificationId', p_notification_id),
    timeout_milliseconds := 5000
  );
  return true;
exception when others then
  -- Notification creation must never fail because transport is unavailable.
  return false;
end;

declare
  v_attempt integer;
  v_delay_seconds integer;
begin
  if p_status not in ('sent', 'no_devices', 'failed') then
    raise exception 'V1_PUSH_STATUS_INVALID' using errcode = '22023';
  end if;
  select outbox.attempt_count into v_attempt
  from public.v1_notification_push_outbox outbox
  where outbox.notification_id = p_notification_id
  for update;
  if v_attempt is null then
    return false;
  end if;
  v_delay_seconds := least(3600, 30 * (2 ^ least(v_attempt, 7))::integer);
  update public.v1_notification_push_outbox outbox
     set status = p_status,
         sent_device_count = greatest(0, coalesce(p_sent_device_count, 0)),
         last_error_code = left(nullif(btrim(coalesce(p_error_code, '')), ''), 120),
         next_attempt_at = case when p_status = 'failed'
           then clock_timestamp() + make_interval(secs => v_delay_seconds)
           else outbox.next_attempt_at end,
         lease_until = null,
         completed_at = case when p_status in ('sent', 'no_devices')
           then clock_timestamp() else null end,
         updated_at = clock_timestamp()
   where outbox.notification_id = p_notification_id;
  return found;
end;

begin
  if nullif(current_setting('request.method', true), '') is not null then
    raise sqlstate 'PGRST' using
      message = jsonb_build_object(
        'code', '40001',
        'message', p_message,
        'details', null,
        'hint', null
      )::text,
      detail = '{"status":409,"headers":{}}';
  end if;

  raise exception '%', p_message using errcode = '40001';
end;

declare
  v_actor uuid := auth.uid();
  v_request_id uuid := nullif(btrim(coalesce(p_payload ->> 'request_id', '')), '')::uuid;
  v_project_id uuid := nullif(btrim(coalesce(p_payload ->> 'project_id', '')), '')::uuid;
  v_existing jsonb;
  v_saved jsonb;
  v_response jsonb;
begin
  if v_actor is null or not public.v1_current_actor_is_active()
    or v_request_id is null or v_project_id is null
    or not public.v1_can_create_material_request(v_project_id) then
    raise exception 'V1_MATERIAL_REQUEST_DRAFT_SAVE_DENIED'
      using errcode = '42501';
  end if;
  if exists (
    select 1 from public.v1_material_requests request_record
    where request_record.id = v_request_id
      and (
        request_record.project_id <> v_project_id
        or request_record.created_by_auth_user_id <> v_actor
      )
  ) then
    raise exception 'V1_MATERIAL_REQUEST_DRAFT_SAVE_DENIED'
      using errcode = '42501';
  end if;

  v_existing := public.v1_idempotency_get_or_claim(
    'v1_save_material_request_draft_idempotent',
    p_idempotency_key,
    p_payload
  );
  if v_existing is not null then return v_existing; end if;

  v_saved := public.v1_save_material_request_draft(p_payload);
  v_response := jsonb_build_object(
    'request_id', v_request_id,
    'record_version', (v_saved ->> 'record_version')::integer,
    'operation_id', p_idempotency_key,
    'payload_hash', public.v1_hash_json(p_payload),
    'committed_at', v_saved ->> 'updated_at'
  );
  perform public.v1_complete_idempotency(
    'v1_save_material_request_draft_idempotent',
    p_idempotency_key,
    v_response
  );
  return v_response;
end;
